@extends('layouts.app') @section('title','User Management') @section('page-title','User Management')
@section('content')<div x-data="userManager({{ Illuminate\Support\Js::from($users) }})" class="space-y-4"><div class="flex justify-between"><input x-model.debounce.300ms="q" placeholder="Search users" aria-label="Search users" class="rounded border p-2.5"><button @click="form={name:'',email:'',role:'Employee',business:'Palma General Store'};editing=null;open=true" class="rounded bg-[#0b1f33] px-4 py-2.5 text-sm text-white">Add User</button></div><div class="overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-gray-50"><tr>@foreach(['Name','Email','Role','Business','Status','Date Created','Actions'] as $h)<th class="p-3">{{ $h }}</th>@endforeach</tr></thead><tbody><template x-for="(u,i) in rows.filter(x=>!q||(x.name+' '+x.email).toLowerCase().includes(q.toLowerCase()))" :key="u.id"><tr class="border-t"><td class="p-3" x-text="u.name"></td><td class="p-3" x-text="u.email"></td><td class="p-3" x-text="u.role"></td><td class="p-3" x-text="u.business||'All businesses'"></td><td class="p-3" x-text="u.status"></td><td class="p-3" x-text="u.created_at"></td><td class="p-3 whitespace-nowrap"><button @click="form={...u};editing=i;open=true" class="text-teal-800 underline">Edit</button><button @click="selected=u;index=i;confirmOpen=true" class="ml-2 text-red-700 underline">Deactivate</button></td></tr></template><tr x-show="!rows.filter(x=>!q||(x.name+' '+x.email).toLowerCase().includes(q.toLowerCase())).length"><td colspan="7" class="p-8 text-center">No users match this search.</td></tr></tbody></table></div><div x-show="open" x-cloak class="fixed inset-0 z-40 grid place-items-center bg-black/50 p-4"><form @submit.prevent="save()" class="w-full max-w-lg space-y-3 rounded-xl bg-white p-6" x-trap.inert.noscroll="open||confirmOpen" role="dialog" aria-modal="true"><h2 class="text-lg font-semibold" x-text="editing===null?'Add User':'Edit User'"></h2><label class="block text-sm">Name<input required x-model="form.name" class="mt-1 w-full rounded border p-2.5"></label><label class="block text-sm">Email<input required type="email" x-model="form.email" class="mt-1 w-full rounded border p-2.5"></label><label class="block text-sm">Role<select x-model="form.role" required class="mt-1 w-full rounded border p-2.5"><option>System Administrator</option><option>Business Owner</option><option>HR/Manager</option><option>Payroll Officer</option><option>Employee</option></select></label><label class="block text-sm">Business assignment<input :required="form.role!=='System Administrator'" x-model="form.business" :disabled="form.role==='System Administrator'" class="mt-1 w-full rounded border p-2.5"></label><div class="flex justify-end gap-2"><button type="button" @click="open=false" class="rounded border px-4 py-2">Cancel</button><button class="rounded bg-[#0b1f33] px-4 py-2 text-white">Save</button></div></form></div><div x-show="confirmOpen" x-cloak class="fixed inset-0 z-40 grid place-items-center bg-black/50 p-4"><div x-trap.inert.noscroll="open||confirmOpen" role="dialog" aria-modal="true" class="w-full max-w-md rounded-xl bg-white p-6"><h2 class="text-lg font-semibold">Deactivate user?</h2><p class="my-3 text-sm" x-text="selected?.name"></p><div class="flex justify-end gap-2"><button @click="confirmOpen=false" class="rounded border px-4 py-2">Cancel</button><button @click="rows[index].status='Inactive';confirmOpen=false;$dispatch('show-toast',{message:'User deactivated (demo).'})" class="rounded bg-red-700 px-4 py-2 text-white">Confirm</button></div></div></div></div><script>function userManager(rows){return {rows,q:'',open:false,confirmOpen:false,form:{},editing:null,selected:null,index:0,save(){if(this.form.role!=='System Administrator'&&!this.form.business)return;if(this.editing===null)this.rows.push({...this.form,id:Date.now(),status:'Active',created_at:new Date().toISOString().slice(0,10)});else this.rows[this.editing]={...this.rows[this.editing],...this.form};this.open=false;this.$dispatch('show-toast',{message:'User saved (demo).'})}}}</script>@endsection
